(function(){const Q=window.DIAGNOSTIC_QUESTIONS,P=window.PROFILE_QUESTIONS,$=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])),shuffle=a=>a.map(v=>[Math.random(),v]).sort((a,b)=>a[0]-b[0]).map(x=>x[1]);let identity={},profile={},started=0,seconds=1200,timer,done=false;
function show(id){['#welcome','#profileStep','#quizStep','#resultStep'].forEach(x=>$(x).classList.toggle('hidden',x!==id));scrollTo({top:0,behavior:'smooth'})}
$('#identityForm').addEventListener('submit',e=>{e.preventDefault();identity={student_name:$('#studentName').value.trim(),class_name:$('#studentClass').value.trim(),group_name:$('#studentGroup').value.trim()};if(identity.student_name.length<2||!identity.class_name)return;renderProfile();show('#profileStep')});
function renderProfile(){$('#profileForm').innerHTML=P.map((q,i)=>`<fieldset class="profile-card"><legend>${i+1}. ${esc(q.fr)}<span class="arabic">${esc(q.ar)}</span></legend><div class="option-list">${q.options.map(o=>`<label class="option"><input type="radio" name="${q.id}" value="${o[0]}"><span>${esc(o[1])}<span class="arabic">${esc(o[2])}</span></span></label>`).join('')}</div></fieldset>`).join('')}
$('#startQuiz').onclick=()=>{P.forEach(q=>profile[q.id]=$(`#profileForm input[name="${q.id}"]:checked`)?.value||'non_repondu');renderQuiz();started=Date.now();timer=setInterval(tick,1000);show('#quizStep')};
function renderQuiz(){$('#quizForm').innerHTML=Q.map((q,i)=>`<fieldset class="question" id="card-${q.id}"><div class="q-head"><span class="q-number">${i+1}</span><legend class="q-title">${esc(q.fr)}<span class="arabic">${esc(q.ar)}</span></legend></div><div class="option-list">${shuffle(q.options).map(o=>`<label class="option"><input type="radio" name="${q.id}" value="${o[0]}"><span>${esc(o[1])}<span class="arabic">${esc(o[2])}</span></span></label>`).join('')}</div><p class="feedback"></p></fieldset>`).join('');$('#quizForm').addEventListener('change',progress)}
function progress(){const n=Q.filter(q=>$(`input[name="${q.id}"]:checked`)).length;$('#answeredLabel').textContent=`${n} / ${Q.length}`;$('#progressBar').style.width=`${n/Q.length*100}%`}
function tick(){seconds--;$('#clock').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;$('#timer').classList.toggle('warning',seconds<=300&&seconds>60);$('#timer').classList.toggle('danger',seconds<=60);if(seconds<=0){clearInterval(timer);submit(true)}}
$('#submitQuiz').onclick=()=>submit(false);
async function submit(auto){if(done)return;const n=Q.filter(q=>$(`input[name="${q.id}"]:checked`)).length;if(!auto&&n<Q.length&&!confirm(`Vous avez répondu à ${n} question(s) sur ${Q.length}. Valider quand même ?`))return;done=true;clearInterval(timer);const answers={},domains={'Connaissances informatiques':{correct:0,total:0},'Logique générale':{correct:0,total:0}};let correct=0;Q.forEach(q=>{const chosen=$(`input[name="${q.id}"]:checked`)?.value||null,ok=chosen===q.correct;answers[q.id]=chosen;domains[q.domain].total++;if(ok){correct++;domains[q.domain].correct++}const card=$(`#card-${q.id}`);card.classList.add(ok?'correct':'incorrect');card.querySelector('.feedback').textContent=ok?'Réponse correcte · جواب صحيح':`Réponse attendue : ${q.options.find(o=>o[0]===q.correct)[1]}`;card.querySelectorAll('input').forEach(x=>x.disabled=true)});const score=correct*2,level=score>=16?'Acquis solides':score>=10?'Acquis à consolider':'Remédiation prioritaire';showResult(score,level,domains);const row={...identity,equipment_profile:profile,answers,domain_scores:domains,score,level,duration_seconds:Math.min(7200,Math.round((Date.now()-started)/1000)),quiz_version:window.APP_CONFIG.quizVersion};try{await window.DiagnosticAPI.submit(row);$('#saveState').textContent='✓ Copie enregistrée et transmise au professeur.';$('#saveState').className='save-state ok'}catch(e){$('#saveState').textContent="La copie n'a pas pu être transmise. Vérifiez Internet et prévenez le professeur.";$('#saveState').className='save-state error'}}
function showResult(score,level,domains){show('#resultStep');$('#scoreText').textContent=`${score}/20`;$('#scoreRing').style.setProperty('--pct',`${score*5}%`);$('#levelText').textContent=level;const m=score>=16?["Les prérequis essentiels sont maîtrisés.",'المكتسبات الأساسية متحكم فيها.']:score>=10?["Plusieurs bases sont présentes, mais elles doivent être consolidées.",'توجد مكتسبات أولية تحتاج إلى التثبيت.']:["Les prérequis sont fragiles. Une remédiation progressive est conseillée.",'المكتسبات القبلية ضعيفة وتحتاج إلى دعم تدريجي.'];$('#resultMessage').textContent=m[0];$('#resultArabic').textContent=m[1];$('#domainCards').innerHTML=Object.entries(domains).map(([k,v])=>`<div class="domain-card"><span>${esc(k)}</span><strong>${v.correct*2}/10</strong><small>${v.correct} réponse(s) correcte(s) sur ${v.total}</small></div>`).join('')}
})();
